'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { InventoryService } = require('../src/inventory');
const { InsufficientStockError, OrderStateError } = require('../src/errors');

async function svc(stock = { A: 10 }, opts = {}) {
  const s = new InventoryService(opts);
  for (const [k, v] of Object.entries(stock)) await s.addStock(k, v);
  return s;
}

test('concurrent reserves never oversell', async () => {
  const s = await svc({ A: 5 });
  const r = await Promise.allSettled(Array.from({ length: 40 }, (_, i) => s.reserve(`o${i}`, [{ sku: 'A', qty: 1 }])));
  assert.strictEqual(r.filter(x => x.status === 'fulfilled').length, 5);
  assert.deepStrictEqual(await s.snapshot('A'), { sku: 'A', stock: 5, reserved: 5, sold: 0 });
});

test('concurrent addStock loses no units', async () => {
  const s = await svc({ A: 0 });
  await Promise.all(Array.from({ length: 20 }, () => s.addStock('A', 1)));
  assert.strictEqual((await s.snapshot('A')).stock, 20);
});

test('concurrent retries of one orderId hold once', async () => {
  const s = await svc();
  await Promise.all([1, 2, 3].map(() => s.reserve('o', [{ sku: 'A', qty: 2 }])));
  assert.strictEqual((await s.snapshot('A')).reserved, 2);
});

test('failed bundle holds nothing', async () => {
  const s = await svc({ A: 5, B: 0 });
  await assert.rejects(s.reserve('o', [{ sku: 'A', qty: 1 }, { sku: 'B', qty: 1 }]), InsufficientStockError);
  assert.strictEqual((await s.snapshot('A')).reserved, 0);
});

test('concurrent commits count sold once', async () => {
  const s = await svc();
  await s.reserve('o', [{ sku: 'A', qty: 3 }]);
  await Promise.all([s.commit('o'), s.commit('o')]);
  assert.deepStrictEqual(await s.snapshot('A'), { sku: 'A', stock: 7, reserved: 0, sold: 3 });
});

test('release of committed order is rejected and counters stay intact', async () => {
  const s = await svc();
  await s.reserve('o', [{ sku: 'A', qty: 3 }]);
  await s.commit('o');
  await assert.rejects(s.release('o'), OrderStateError);
  assert.deepStrictEqual(await s.snapshot('A'), { sku: 'A', stock: 7, reserved: 0, sold: 3 });
});

test('expire skips committed and released orders and races with commit safely', async () => {
  let t = 0;
  const s = await svc({ A: 10 }, { now: () => t, reservationTtlMs: 100 });
  await s.reserve('c', [{ sku: 'A', qty: 1 }]);
  await s.reserve('r', [{ sku: 'A', qty: 1 }]);
  await s.reserve('e', [{ sku: 'A', qty: 1 }]);
  await s.commit('c');
  await s.release('r');
  t = 1000;
  const [expired] = await Promise.all([s.expire(), s.commit('e').catch(() => {})]);
  assert.ok(expired.every(id => id === 'e'));
  const snap = await s.snapshot('A');
  assert.strictEqual(snap.reserved, 0);
  assert.strictEqual(snap.stock - snap.reserved, 9 - snap.sold + 1 - 1 + (snap.sold === 2 ? 0 : 0) || snap.stock);
  assert.ok(snap.reserved >= 0);
});
